using System.Diagnostics;
using System.Reflection;
using Buildvana.Sdk.SourceGenerators;

/// <summary>
/// Provides the parts that every generated file shares, as a test expects them.
/// </summary>
internal static class ExpectedGuestCode
{
    public const string AutoGeneratedComment = """
        // <auto-generated>
        // This file was automatically generated by Buildvana.Sdk. DO NOT MODIFY!
        // </auto-generated>
        """;

    public const string FileHeader = $"""
        {AutoGeneratedComment}

        #nullable enable
        """;

    public static string PackageVersion { get; } = GetPackageVersion();

    private static string GetPackageVersion()
    {
        var attribute = typeof(ThisAssemblyClassGenerator).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>();
        Debug.Assert(attribute is not null, "The .NET SDK gives every assembly it builds an informational version.");
        return attribute.InformationalVersion;
    }
}
